import React from 'react';

import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Empty from '@ui-kit/Empty';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList, { IPohListItem } from '@ui-kit/List';

import ClubListItem from './ClubListItem';
import { getClubsAsync } from '../@services/clubs.service';
import { IGetClubsCriteria } from '../@types/clubs.dto.types';
import { IClub } from '../@types/clubs.types';

interface IClubsListProps {
  criteria?: IGetClubsCriteria;
  listItemPatcher?: (club: IClub) => Partial<IPohListItem>;
  withSearch?: boolean;
}

const ClubsList = (props: IClubsListProps = {}) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [data, setData] = React.useState<IClub[]>([]);
  const [err, setErr] = React.useState<Error>();
  const [q, setQ] = React.useState('');

  React.useEffect(() => {
    const fetchData = async () => {
      try {
        setIsLoading(true);

        const dt = await getClubsAsync(props.criteria);

        setData(dt);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [props.criteria]);

  const filteredData = React.useMemo(() => {
    if (!props.withSearch || !q.length) return data;
    return data.filter((x) => x.name.toLocaleLowerCase().includes(q.toLowerCase()));
  }, [data, q, props.withSearch]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  if (!data.length) {
    return <Empty>Нет клубов</Empty>;
  }

  return (
    <>
      <section>
        {!!props.withSearch && (
          <header className="pb-2">
            <PohInput type={InputTypes.search} value={q} onChange={setQ} placeholder="Найти" />
          </header>
        )}
        <div style={{ overflowY: 'auto', maxHeight: 400 }}>
          <PohList
            data={filteredData.map((x) => {
              return {
                key: x.id,
                children: <ClubListItem club={x} />,
                ...(props.listItemPatcher ? props.listItemPatcher(x) : {}),
              };
            })}
          />
        </div>
      </section>
    </>
  );
};

export default ClubsList;
